CREATE TABLE `zendendb`.`StrakhovyeVznosyPoFizicheskimLitsam` (`DataNachala` Nullable(Date32) COMMENT 'ДатаНачала', `StatyaFinansirovaniya` Nullable(String) COMMENT 'СтатьяФинансирования', `StatyaRaskhodov` Nullable(String) COMMENT 'СтатьяРасходов', `Sotrudnik` Nullable(String) COMMENT 'Сотрудник', `SotrudnikGuid` UUID COMMENT 'СотрудникГуид = Уникальный идентификатор(Сотрудник)', `Podrazdelenie` Nullable(String) COMMENT 'Подразделение', `Nachislenie` Nullable(String) COMMENT 'Начисление', `PFRDoPredelnoyVelichiny` Nullable(Decimal(15, 2)) COMMENT 'ПФРДоПредельнойВеличины', `PFRSPrevysheniya` Nullable(Decimal(15, 2)) COMMENT 'ПФРСПревышения', `PFRPoSummarnomuTarifu` Nullable(Decimal(15, 2)) COMMENT 'ПФРПоСуммарномуТарифу', `FSS` Nullable(Decimal(15, 2)) COMMENT 'ФСС', `FSSNeschastnyeSluchai` Nullable(Decimal(15, 2)) COMMENT 'ФССНесчастныеСлучаи', `FFOMS` Nullable(Decimal(15, 2)) COMMENT 'ФФОМС', `PFRNaDoplatuLetchikam` Nullable(Decimal(15, 2)) COMMENT 'ПФРНаДоплатуЛетчикам', `PFRNaDoplatuSHakhteram` Nullable(Decimal(15, 2)) COMMENT 'ПФРНаДоплатуШахтерам', `PFRZaZanyatykhNaPodzemnykhIVrednykhRabotakh` Nullable(Decimal(15, 2)) COMMENT 'ПФРЗаЗанятыхНаПодземныхИВредныхРаботах', `PFRZaZanyatykhNaTyazhelykhIProchikhRabotakh` Nullable(Decimal(15, 2)) COMMENT 'ПФРЗаЗанятыхНаТяжелыхИПрочихРаботах', `PFRStrakhovaya` Nullable(Decimal(15, 2)) COMMENT 'ПФРСтраховая', `PFRNakopitelnaya` Nullable(Decimal(15, 2)) COMMENT 'ПФРНакопительная', `TFOMS` Nullable(Decimal(15, 2)) COMMENT 'ТФОМС', `PFRZaZanyatykhNaPodzemnykhIVrednykhRabotakhBezSpetsOtsenki` Nullable(Decimal(15, 2)) COMMENT 'ПФРЗаЗанятыхНаПодземныхИВредныхРаботахБезСпецОценки', `PFRZaZanyatykhNaPodzemnykhIVrednykhRabotakhSpetsOtsenka` Nullable(Decimal(15, 2)) COMMENT 'ПФРЗаЗанятыхНаПодземныхИВредныхРаботахСпецОценка', `PFRZaZanyatykhNaTyazhelykhIProchikhRabotakhBezSpetsOtsenki` Nullable(Decimal(15, 2)) COMMENT 'ПФРЗаЗанятыхНаТяжелыхИПрочихРаботахБезСпецОценки', `PFRZaZanyatykhNaTyazhelykhIProchikhRabotakhSpetsOtsenka` Nullable(Decimal(15, 2)) COMMENT 'ПФРЗаЗанятыхНаТяжелыхИПрочихРаботахСпецОценка', `PodrazdelenieKodMagazina` Nullable(Int16) COMMENT 'ПодразделениеКодПодразделения', `Period` DateTime64(0) COMMENT 'Период', `ParametrPeriodSegment` DateTime64(0) COMMENT 'Параметр.ПериодСегмент', INDEX StrakhovyeVznosyPoFizicheskimLitsam_Segment_idx ParametrPeriodSegment TYPE minmax GRANULARITY 1) ENGINE = ReplicatedMergeTree() PARTITION BY toYear(Period) PRIMARY KEY (Period, SotrudnikGuid) ORDER BY (Period, SotrudnikGuid) SETTINGS replace_long_file_name_to_hash = 1, index_granularity = 8192 COMMENT 'СтраховыеВзносыПоФизическимЛицам';

