CREATE TABLE `zendendb`.`ТоварыУПП_backup` (`ТоварГуид` String, `Товар` String, `Артикул` String, `КодДляОбмена` UInt32, `СвойствоВидОбуви` String, `СвойствоГод` String, `СвойствоМатериалВерха` String, `СвойствоРод` String, `СвойствоСезон` String, `СвойствоТорговаяМарка` String, `ТипНоменклатуры` String, `СтавкаНДС` String, `OrderTM` String, `СвойствоКоллекцияПроизводства` String, `СвойствоКоллекцияПроизводстваКомментарий` String, `ПовторАналогНовинка` String, `Полнота` Int32, `СвойствоБренд` String, `СвойствоВидДетскойОбуви` String, `СвойствоВидТкани` String, `СвойствоВкладнаяСтелька` String, `СвойствоВозрастнаяГруппаОбуви` String, `СвойствоВысотаКаблука` String, `СвойствоКреплениеКаблука` String, `СвойствоМатериалПодкладки` String, `СвойствоПодвидОбуви` String, `СвойствоПодсезон` String, `СвойствоПодстиль` String, `СвойствоПризнак` String, `СвойствоПроизводитель` String, `СвойствоРазмерОдежды` String, `СвойствоРазмерТовара` String, `СвойствоСтиль` String, `СвойствоЦвет` String, `СтранаПроисхождения` String) ENGINE = ReplicatedMergeTree() PRIMARY KEY `ТоварГуид` ORDER BY `ТоварГуид` SETTINGS replace_long_file_name_to_hash = 1, index_granularity = 8192;

CREATE TABLE `zendendb`.`ТоварыУППКомментарии` (`СвойствоНоменклатурыГуид` String, `Наименование` String, `Код` LowCardinality(String), `Комментарий` LowCardinality(String)) ENGINE = ReplicatedMergeTree() ORDER BY `СвойствоНоменклатурыГуид` SETTINGS index_granularity = 8192;

CREATE TABLE `zendendb`.`ТоварыУчаствующиеВАкции` (`Период` DateTime, `НомерСтроки` UInt32, `ОрганизацияГуид` String, `Организация` String, `НоменклатураГуид` String, `Номенклатура` String, `Акция` String, `Скидка` Decimal(8, 2), `ПроцентСкидки` Decimal(7, 4), `Цена` Decimal(8, 2), `ДатаНачала` Date, `ДатаОкончания` Date) ENGINE = ReplicatedMergeTree() PARTITION BY toYYYYMMDD(`Период`) ORDER BY (`НоменклатураГуид`, `ОрганизацияГуид`) SETTINGS index_granularity = 8192 COMMENT 'ТоварыУчаствующиеВАкции из 1с';

CREATE TABLE `zendendb`.`ТорговаяМаркаПроект` (`СвойствоТорговаяМарка` String, `Проект` LowCardinality(String)) ENGINE = ReplicatedReplacingMergeTree() ORDER BY `СвойствоТорговаяМарка` SETTINGS index_granularity = 8192;

CREATE TABLE `zendendb`.`Укомплектованность` (`Дата` Date, `Магазин Родитель` String, `Подразделение` String, `Город` String, `ТипМагазина` String, `Должность` String, `ДолжностьГуид` String, `Территориальный Менеджер` String, `План` Decimal(5, 2), `Факт` Decimal(5, 2), `КодМагазина` UInt32) ENGINE = ReplicatedReplacingMergeTree() ORDER BY (`Дата`, `ДолжностьГуид`) SETTINGS index_granularity = 8192 COMMENT 'Отчет по укомплектованности персоналом магазинов';

CREATE TABLE `zendendb`.`ФОТ/ТО` (`Месяц` Date, `СотрудникГуид` String, `Сотрудник` String, `Должность` String, `ДолжностьУправленческая` String, `Организация` LowCardinality(String), `СтатьяФинансирования` String, `Подразделение` LowCardinality(String), `ПодразделениеУправленческое` LowCardinality(String), `КодМагазина` Int32, `ТМ` LowCardinality(String), `РМ` LowCardinality(String), `Магазин Родитель` LowCardinality(String), `Город` LowCardinality(String), `Регион` LowCardinality(String), `ОтработаноДней` Int32, `ОтработаноЧасов` Int32, `ПФР по суммарному тарифу` Nullable(Decimal(15, 3)), `ФСС НС` Nullable(Decimal(15, 3)), `НДФЛ` Nullable(Decimal(15, 3)), `Районный коэффициент` Nullable(Decimal(15, 3)), `Праздничные и вых. дни` Nullable(Decimal(15, 3)), `Оклад` Nullable(Decimal(15, 3)), `Премия` Nullable(Decimal(15, 3)), `Отпуск` Nullable(Decimal(15, 3)), `Командировка` Nullable(Decimal(15, 3)), `Больничный` Nullable(Decimal(15, 3)), `Комп отпуска при увольнении` Nullable(Decimal(15, 3)), `Северная надбавка` Nullable(Decimal(15, 3)), `Удержание по исполнительному документу` Nullable(Decimal(15, 3)), `Мат помощь` Nullable(Decimal(15, 3)), `Компенсация по соглашению сторон` Nullable(Decimal(15, 3)), `ШтатФакт` Nullable(Decimal(15, 3)), `ШтатПлан` Nullable(Decimal(15, 3)), `Укомплектованность` Nullable(Decimal(15, 3)), `Количество` Int64, `ТО` Nullable(Decimal(15, 3)), `Вал` Nullable(Decimal(15, 3)), `Трафик` Nullable(Decimal(15, 3)), `Пары` Int64, `Чеки покупок` Int32, `Чеки возвратов` Int32, `План Оборот` Nullable(Decimal(15, 3)), `План Трафик` Nullable(Decimal(15, 3)), `План Вал` Nullable(Decimal(15, 3)), `План Чеки` Nullable(Decimal(15, 3)), `План Пары` Nullable(Decimal(15, 3)), `Вентра Часов день` Nullable(Decimal(15, 3)), `Вентра Всего без НДС` Nullable(Decimal(15, 3))) ENGINE = ReplicatedReplacingMergeTree() PARTITION BY toYear(`Месяц`) ORDER BY (`Месяц`, `СотрудникГуид`, `КодМагазина`, `ДолжностьУправленческая`) SETTINGS index_granularity = 8192 COMMENT 'Отчет соотношению ТО и ФОТ по магазинам и работникам';

CREATE TABLE `zendendb`.`ФизическиеЛица` (`ДатаРождения` Date, `Должность` String, `НомерПродавца` Int16, `Уволен` Bool, `Совместитель` Bool, `Организация` String, `Актуальный` Bool, `ДатаЗаведения` Date, `Пол` String, `НеУчитыватьПродажи` Bool, `Зал` String, `Родитель` String, `Наименование` String, `Код` String, `ОрганизацияГуид` String, `ПродавецГуид` String, `Ссылка` String) ENGINE = ReplicatedMergeTree() PARTITION BY `Должность` PRIMARY KEY `ПродавецГуид` ORDER BY `ПродавецГуид` SETTINGS index_granularity = 8192 COMMENT 'ФизическиеЛица из 1с';

CREATE TABLE `zendendb`.`ЦеныНоменклатуры` (`Период` DateTime, `ТоварГуид` String, `ТипЦен` String, `ТипЦенГуид` String, `Цена` Decimal(15, 2)) ENGINE = ReplicatedMergeTree() PARTITION BY toYYYYMMDD(`Период`) ORDER BY (`Период`, `ТоварГуид`, `ТипЦенГуид`) SETTINGS index_granularity = 8192 COMMENT 'ЦеныНоменклатуры из 1с';

CREATE TABLE `zendendb`.`ЦеныНоменклатурыOMS` (`ID` Int32, `XML_ID` String, `PRODUCT_ID` Int32, `PRICE` Decimal(10, 3), `TIMESTAMP_X` DateTime, `PRICE_SCALE` Decimal(10, 3)) ENGINE = ReplicatedReplacingMergeTree() PARTITION BY toYear(TIMESTAMP_X) ORDER BY (toDate(TIMESTAMP_X), PRODUCT_ID, ID) SETTINGS index_granularity = 8192 COMMENT 'ЦеныНоменклатуры из OMS';

CREATE TABLE `zendendb`.`ЦеныНоменклатуры_2005-2022` (`Период` DateTime, `ТоварГуид` String, `КодДляОбмена` UInt64, `Товар` String, `ТипЦен` LowCardinality(String), `ТипЦенГуид` LowCardinality(String), `Цена` Decimal(15, 2), `Дата записи` DateTime DEFAULT `Период`) ENGINE = ReplicatedReplacingMergeTree() PARTITION BY toYear(`Период`) ORDER BY (`ТоварГуид`, `Период`, `ТипЦен`) SETTINGS index_granularity = 8192;

CREATE TABLE `zendendb`.`ЦеныНоменклатурыЦР` (`Период` DateTime, `НомерСтроки` UInt32, `Активность` Bool, `ТипЦен` String, `ПодразделениеГуидТипЦен` String, `ПодразделениеТипЦен` String, `РодительТипЦен` String, `НоменклатураГуид` String, `Номенклатура` String, `ХарактеристикаНоменклатуры` String, `Валюта` String, `Цена` Decimal(15, 2), `ЕдиницаИзмерения` String, `ПроцентСкидкиНаценки` Decimal(5, 2)) ENGINE = ReplicatedMergeTree() PARTITION BY toYYYYMMDD(`Период`) ORDER BY (`НоменклатураГуид`, `ПодразделениеГуидТипЦен`, `Период`) SETTINGS index_granularity = 8192 COMMENT 'ЦеныНоменклатуры ЦР из 1с';

CREATE TABLE `zendendb`.`ЧасовыеПояса` (`Округ` String, `Город` String, `Относительно Москвы` Int8) ENGINE = ReplicatedReplacingMergeTree() PARTITION BY `Округ` ORDER BY `Город` SETTINGS index_granularity = 8192;

CREATE TABLE `zendendb`.`ШтатноеРасписание` (`ШтатноеРасписаниеГуид` UUID COMMENT 'ШтатноеРасписаниеГуид = Уникальный идентификатор(Ссылка)', `ДатаВыгрузки` DateTime64(0) COMMENT 'ДатаВыгрузки = Текущая дата()', `ГоловнаяОрганизация` String COMMENT 'ГоловнаяОрганизация', `Наименование` String COMMENT 'Наименование = Отсечь незначащие символы(Наименование)', `КодМагазина` Int16 COMMENT 'КодМагазина = Отсечь незначащие символы(КодМагазина)', `ПодразделениеГуид` UUID COMMENT 'ПодразделениеГуид = Уникальный идентификатор(Подразделение)', `Подразделение` String COMMENT 'Подразделение = Отсечь незначащие символы(Подразделение)', `Должность` String COMMENT 'Должность = Отсечь незначащие символы(Должность)', `ГрафикРаботыСотрудников` String COMMENT 'ГрафикРаботыСотрудников = Отсечь незначащие символы(ГрафикРаботыСотрудников)', `КоличествоСтавок` Decimal(38, 6) COMMENT 'КоличествоСтавок = Если тип число(КоличествоСтавок)', `ДатаУтверждения` DateTime64(0) COMMENT 'ДатаУтверждения = Если тип дата(ДатаУтверждения)', `Закрыта` Bool COMMENT 'Закрыта = Если тип булево(Закрыта)', `ДатаЗакрытия` DateTime64(0) COMMENT 'ДатаЗакрытия = Если тип дата(ДатаЗакрытия)', `ДолжностьУправленческая` String COMMENT 'ДолжностьУправленческая = Отсечь незначащие символы(ДолжностьУправленческая)') ENGINE = ReplicatedMergeTree() PRIMARY KEY (`ШтатноеРасписаниеГуид`, `ДатаВыгрузки`) ORDER BY (`ШтатноеРасписаниеГуид`, `ДатаВыгрузки`) SETTINGS replace_long_file_name_to_hash = 1, index_granularity = 8192 COMMENT 'ШтатноеРасписание';

